#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Write build/vitamin-c-quiz-EN.json: one question per numbered finding (45), grounded in the vault
findings.md. The correct option is written first; build_en_vitamin_c.py rebalances the answer key
deterministically (lab lesson 14)."""
import json, pathlib

