assert len(Q) == 45, len(Q)
out = []
for i, (tier, q, opts, why) in enumerate(Q, 1):
    assert len(opts) == 4, i
    for s in [q, why] + opts:
        assert "</" not in s and "&" not in s, (i, s)
    out.append({"n": i, "tier": tier, "q": q, "options": opts, "a": 0, "why": why})
p = pathlib.Path(__file__).resolve().parent / "vitamin-c-quiz-EN.json"
p.write_text(json.dumps({"questions": out}, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
print("wrote", p, len(out))
